"""Check the workspace boundary without reading or writing user files."""

import unittest
from guard import allow_write


class GuardTests(unittest.TestCase):
    def test_workspace_files(self):
        for path in ("workspace", "workspace/note.md", "workspace/docs/readme.md"):
            with self.subTest(path=path):
                self.assertTrue(allow_write(path))

    def test_sibling_prefixes(self):
        for path in ("workspace-old/note.md", "workspace2/note.md", "workspaceevil"):
            with self.subTest(path=path):
                self.assertFalse(allow_write(path))

    def test_traversal_and_unrelated(self):
        for path in ("", ".", "docs/note.md", "workspace/../private.md", "../workspace/a"):
            with self.subTest(path=path):
                self.assertFalse(allow_write(path))

    def test_absolute_path(self):
        self.assertFalse(allow_write(chr(47) + "workspace/note.md"))


if __name__ == "__main__":
    unittest.main()
